mapper.select:
SELECT action.strategy_action_id, action.strategy_option_id, action.action_type, action.action_quantity, action.action_order, action.start_date, action.end_date, source_point.sales_point_id AS source_sales_point_id, source_point.sales_point_code AS source_sales_point_code, source_point.sales_point_name AS source_sales_point_name, target_point.sales_point_id AS target_sales_point_id, target_point.sales_point_code AS target_sales_point_code, target_point.sales_point_name AS target_sales_point_name, source_warehouse.warehouse_id AS source_warehouse_id, source_warehouse.warehouse_code AS source_warehouse_code, source_warehouse.warehouse_name AS source_warehouse_name, destination_warehouse.warehouse_id AS destination_warehouse_id, destination_warehouse.warehouse_code AS destination_warehouse_code, destination_warehouse.warehouse_name AS destination_warehouse_name FROM strategy_action action LEFT JOIN sales_point source_point ON source_point.sales_point_id = action.source_sales_point_id AND source_point.is_deleted = 0 LEFT JOIN sales_point target_point ON target_point.sales_point_id = action.target_sales_point_id AND target_point.is_deleted = 0 LEFT JOIN warehouse source_warehouse ON source_warehouse.warehouse_id = action.source_warehouse_id AND source_warehouse.is_deleted = 0 LEFT JOIN warehouse destination_warehouse ON destination_warehouse.warehouse_id = action.destination_warehouse_id AND destination_warehouse.is_deleted = 0 WHERE action.is_deleted = 0 AND action.strategy_option_id IN
#{strategyOptionId}
ORDER BY action.strategy_option_id, action.action_order NULLS LAST, action.strategy_action_id
